/* Villain Study uses supplied answers and evidence, never a live model. */
const villainKeys={progress:'gtoTrainer.villainProgress.v1',recent:'gtoTrainer.villainRecent.v1',baselines:'gtoTrainer.spotBaselines.v1'};
function readVillain(k,fallback){try{return JSON.parse(localStorage.getItem(villainKeys[k]))??fallback}catch{return fallback}}
function writeVillain(k,v){try{localStorage.setItem(villainKeys[k],JSON.stringify(v))}catch{toast('Storage unavailable. Export your progress to keep it.')}}
let villainProgress=readVillain('progress',[]),spotBaselines=readVillain('baselines',[]),villainPicker=SpotEngine.createPicker({recent:readVillain('recent',[])});
function withBaseline(s){const b=spotBaselines.find(b=>b.spotId===s.id&&b.tableSize===s.tableSize);return b?{...s,baseline:b}:s}
function villainPool(){return (villainData?.spots||[]).map(withBaseline).filter(s=>s.tableSize===settings.tableSize&&SpotEngine.sample(s)!=='hidden'&&(!filters.villain||filters.villain==='All'||s.villain===filters.villain)&&(!filters.kind||filters.kind==='Both'||s.kind===(filters.kind==='Real'?'villain_real':'villain_fabricated'))&&(!filters.template||filters.template==='All'||s.template===filters.template)&&(!filters.difficulty||filters.difficulty==='All'||s.difficulty===Number(filters.difficulty))&&(filters.grading!=='baseline'||s.baseline))}
function optionLabel(a){return ({fold:'Fold',call:'Call',check:'Check',raise:'Raise','3bet':'3-bet','4bet':'4-bet',check_or_fold:'Check / fold',raise_4_5bb:'Raise to 4–5bb','3bet_value':'3-bet for value'})[a]||a.replace(/^bet_(\d+)pct$/,'Bet $1% pot').replace(/_/g,' ')}
function villainSetup(){if(!opponentProfiles||!villainData){shell('<div class="page"><h1>Villain data unavailable.</h1><p>Reconnect and reload to prepare the notebook.</p></div>');return}filters.grading??='exploit';const pool=villainPool();shell(`<div class="page"><button class="back" data-go="home">${svgIcon('back')} All practice modes</button><div class="eyebrow">Read the player</div><h1>Villain Study</h1><p class="muted">Real hands and constructed tests from your home-game notebook. Exploit read, not solver output.</p>${tableSwitch()}<section class="panel villain-filters">${[['villain','Villain',['All',...Object.keys(opponentProfiles.players).filter(n=>n!=='Tiger')]],['kind','Kind',['Both','Real','Constructed']],['template','Template',['All',...Object.keys(villainData.templates)]],['difficulty','Difficulty',['All',1,2,3]],['grading','Grading',['exploit','baseline','both']]].map(([key,label,options])=>`<label>${label}<select data-villain-filter="${key}">${options.map(v=>`<option value="${v}" ${(filters[key]??options[0])==v?'selected':''}>${key==='template'&&v!=='All'?esc(villainData.templates[v].title):key==='grading'?({exploit:'Exploit vs villain',baseline:'Baseline',both:'Both'})[v]:esc(v)}</option>`).join('')}</select></label>`).join('')}<p>${pool.length} available spots · ${pool.filter(s=>SpotEngine.sample(s)==='graded').length} graded · ${pool.filter(s=>SpotEngine.sample(s)==='lean').length} lean</p><p class="source">Under 30 observations: hidden. 30–99: lean, no score. 100+: graded. No spot repeats within 20 deals, including across sessions. A narrow filter can run out; widen it to continue.</p><p class="source">Baseline grading uses exact-spot imports. Preflop feedback also offers range comparisons when a bundled or imported full map matches the seats, stack and sizing. Existing six-handed charts are never substituted for four-handed spots.</p><button class="primary" data-start ${pool.length?'':'disabled'}>Start practice ${svgIcon('next')}</button>${!pool.length?`<p class="notice">${filters.grading==='baseline'?'No baseline loaded for this table size.':'No matching villain spots loaded for this table size.'} ${settings.tableSize===6?'The supplied seeds are four-handed; select 4-handed to study them.':'Try broader filters or a different grading mode.'}</p>`:''}</section>${caveats()}<button data-go="villainReview">Review villain mistakes</button></div>`)}
function villainSpot(){const s=villainPicker.next(villainPool(),mistakes);if(s){s.gradingMode=filters.grading||'exploit';writeVillain('recent',villainPicker.snapshot())}return s}
function driverStatsHTML(s){return `<div class="driver-stats">${s.driverStats.map(d=>`<div>${badge(d.n)} ${playerLink(s.villain,d.ref,d.label)}<p>${d.value_pct!==undefined?d.value_pct+'% of observed opportunities':d.value+'bb median'} · n=${d.n}${d.benchmark_pct!==undefined?' · '+(d.benchmark_approximate?'~':'')+d.benchmark_pct+'% break-even folds':''}</p></div>`).join('')}</div>`}
function baselineHTML(s){if(!s.baseline)return '<p class="notice">No baseline loaded for this table size.</p>';const b=s.baseline,frequencies=b.frequencies||{[b.action]:b.freq??1};return `<p><strong>Baseline:</strong> ${Object.entries(frequencies).map(([a,f])=>optionLabel(a)+' '+pct(f)).join(' · ')} when you hold this hand in this spot.</p><p class="source">${esc(b.source)} · ${s.tableSize}-handed</p>`}
function villainFeedback(s,f){if(screen==='session'&&ExploitRanges.isPre(s))return preflopVillainFeedback(s,f);return `<div class="verdict ${f.score===0?'bad':''}"><strong>${f.classification==='lean'?'Lean read, small sample':f.classification==='intentional_deviation'?'Intentional deviation':f.classification==='baseline_unavailable'?'Baseline unavailable':f.score===1?'Correct':f.classification==='baseline_miss'?'Baseline miss':'Exploit miss'}</strong><span class="grade">${f.score===null?'Not scored':f.score+' / 1 point'}</span></div><p>Your answer: <strong>${esc(optionLabel(f.pick))}</strong></p><div class="comparison"><section><h3>Exploit vs ${esc(s.villain)}</h3><p><strong>${esc(optionLabel(s.exploit.best))}</strong></p><p>Acceptable: ${s.exploit.acceptable.map(a=>esc(optionLabel(a))).join(' · ')}</p><p>${esc(s.exploit.why)}</p><p class="source">${esc(s.exploit.rule)}</p></section><section><h3>Baseline</h3>${baselineHTML(s)}${s.baseline?`<p>${SpotEngine.baselineAccepts(s,s.exploit.best)?'Baseline and exploit agree on the best action.':'Baseline and exploit differ on the best action.'}</p>`:''}</section></div>${driverStatsHTML(s)}${s.whatTigerDid?`<p><strong>What Tiger did:</strong> ${esc(s.whatTigerDid)}</p>`:''}<p class="source">Exploit read, not solver output · ${s.tableSize}-handed study · ${esc(s.source.file||s.source.type||'Constructed template')}${s.source.psHandId?' · Hand #'+s.source.psHandId:''}</p>`}
function renderVillain(){const s=session.current,fb=session.feedback;app.innerHTML=`<main class="session villain-session ${fb?'answered':''}"><div class="session-head"><button data-quit>${svgIcon('back')} Save & quit</button><span>Villain Study · ${s.tableSize}-handed</span>${tableSwitch()}<span>Hand ${session.index+1} / ${session.total===Infinity?'∞':session.total}</span></div><div class="progress-track"><i style="width:${session.total===Infinity?((session.index%10)+1)*10:session.index/session.total*100}%"></i></div><div class="eyebrow">${s.kind==='villain_real'?'Real hand':'Constructed'} · ${esc(s.street)} · ${esc(s.gradingMode||'exploit')} mode</div><h2 class="session-title">${esc(s.title)} · ${esc(s.villain)}</h2><p class="session-label">Tiger ${esc(s.heroPos)} vs ${esc(s.villain)} ${esc(s.villainPos)} · ${s.effectiveStackBb??s.stackBb??100}bb effective${s.kind==='villain_real'?' in the logged hand':' · constructed'}</p>${s.tableSizeNote?`<p class="source">${esc(s.tableSizeNote)}</p>`:''}<div class="equity-felt"><div class="hero-hand">${s.heroHand.map(card).join('')}</div>${s.board.length?`<div class="board">${s.board.map(card).join('')}</div>`:''}<p>Pot ${s.potBb}bb · To call ${s.toCallBb}bb</p><p class="source">${s.kind==='villain_real'?'Pot as recorded in the supplied seed at the decision node.':'Constructed decision pot.'}</p></div><details class="panel hand-history" open><summary>Action to this decision</summary><ol>${s.history.map(h=>`<li>${esc(h)}</li>`).join('')}</ol></details><div class="feedback ${fb?'revealed':''}" aria-live="polite">${fb?villainFeedback(s,fb):'<p class="waiting">Choose your action using what you know about this player.</p>'}</div><div class="action-zone">${fb?`<button class="primary equity-next" data-next>${session.index+1>=session.total?'See results':'Next hand'} ${svgIcon('next')}</button>`:`<div class="villain-options">${s.options.map((a,i)=>`<button data-villain-answer="${a}"><small>${i+1}</small> ${esc(optionLabel(a))}</button>`).join('')}</div>`}</div></main>`}
function recordVillain(s,f){
 const row={at:Date.now(),kind:'villain',tableSize:s.tableSize,stackBb:s.effectiveStackBb??s.stackBb??100,rake:0,source:s.source,position:s.heroPos,spot:s.template,mode:'Villain Study',hand:s.id,villain:s.villain,template:s.template,score:f.score,exploitScore:f.exploitScore,baselineScore:f.baselineScore,classification:f.classification,gradingMode:s.gradingMode,pick:f.pick};villainProgress.push(row);writeVillain('progress',villainProgress);session.answers.push(row);
 if(f.score!==null){progress.push(row);write('progress',progress)}
 let m=mistakes.find(m=>m.id===(session.reviewId||s.id));if(['exploit_miss','baseline_miss'].includes(f.classification)){if(!m){m={id:s.id,spot:structuredClone(s),consecutive:0,stage:0,misses:0};mistakes.push(m)}m.lastAt=Date.now();m.wrongPick=f.pick;m.correctAnswer=s.exploit.best;m.misses++;m.consecutive=0;m.due=Date.now();}else if(m&&session.reviewId&&f.score===1){m.consecutive++;if(m.consecutive>=2)mistakes=mistakes.filter(x=>x.id!==m.id);else m.due=Date.now();}write('mistakes',mistakes);
}
function answerVillain(a){if(!session||session.feedback)return;const s=session.current;session.feedback={...SpotEngine.grade(s,a,s.gradingMode||'exploit'),pick:a};recordVillain(s,session.feedback);if(session.feedback.score!==null)feedbackBlip(session.feedback.score);renderVillain()}
function villainProgressHTML(){const rows=villainProgress.filter(p=>p.tableSize===settings.tableSize),group=key=>[...new Set(rows.map(p=>p[key]))].map(k=>{const a=rows.filter(p=>p[key]===k),calc=field=>{const b=a.filter(p=>p[field]!==null&&p[field]!==undefined);return b.length?pct(b.reduce((v,p)=>v+p[field],0)/b.length)+' · '+b.length+' graded':'—'};return `<tr><th>${esc(key==='template'?villainData.templates[k]?.title||k:k)}</th><td>${calc('baselineScore')}</td><td>${calc('exploitScore')}</td><td>${a.filter(p=>p.classification==='baseline_miss').length}</td><td>${a.filter(p=>p.classification==='exploit_miss').length}</td><td>${a.filter(p=>p.classification==='intentional_deviation').length}</td><td>${a.filter(p=>p.classification==='lean').length}</td></tr>`}).join('');return `<section class="panel"><h3>Villain Study · ${settings.tableSize}-handed</h3>${rows.length?['villain','template'].map(key=>`<h4>By ${key}</h4><div class="stat-table-wrap"><table class="opponent-stats"><thead><tr><th>${key}</th><th>Baseline accuracy</th><th>Exploit accuracy</th><th>Baseline misses</th><th>Exploit misses</th><th>Deviations</th><th>Lean (unscored)</th></tr></thead><tbody>${group(key)}</tbody></table></div>`).join(''):'<p class="muted">Study a player to start tracking.</p>'}<button data-go="villainReview">Review villain mistakes</button></section>`}
function showVillainReview(){const queue=mistakes.filter(m=>m.spot.kind?.startsWith('villain_')&&rowSize(m.spot)===settings.tableSize).sort((a,b)=>(b.lastAt||b.due)-(a.lastAt||a.due));shell(`<div class="page"><h1>Villain rematches</h1><p class="muted">${settings.tableSize}-handed · two correct retries in a row retire a spot.</p>${queue.length?queue.map(m=>`<section class="panel"><h3>${esc(m.spot.villain)} · ${esc(m.spot.title)}</h3><p>Your answer: ${esc(optionLabel(m.wrongPick))} · Exploit answer: ${esc(optionLabel(m.spot.exploit.best))}</p>${driverStatsHTML(m.spot)}<p class="source">${m.consecutive} / 2 correct retries</p><button data-villain-retry="${esc(m.id)}">Retry</button></section>`).join(''):'<p class="panel">No villain mistakes in this table size.</p>'}</div>`)}
async function importSpotBaselines(file){try{let d=JSON.parse(await file.text());if(!Array.isArray(d.baselines)||!d.baselines.length)throw Error('Provide a baselines array.');for(let b of d.baselines){let s=villainData.spots.find(s=>s.id===b.spotId&&s.tableSize===b.tableSize);if(!s||typeof b.source!=='string'||!b.source.trim()||!b.frequencies||Object.entries(b.frequencies).some(([a,f])=>!s.options.includes(a)||!Number.isFinite(f)||f<0||f>1)||Math.abs(Object.values(b.frequencies).reduce((a,b)=>a+b,0)-1)>1e-6)throw Error('Invalid spot, source, or normalized frequencies.')}spotBaselines=spotBaselines.filter(b=>!d.baselines.some(x=>x.spotId===b.spotId&&x.tableSize===b.tableSize)).concat(d.baselines);writeVillain('baselines',spotBaselines);toast(d.baselines.length+' exact-spot baselines loaded.')}catch(e){toast('Baseline import rejected: '+e.message)}}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b||b.disabled)return;if(b.dataset.drillPlayer){selectedMode=10;filters={villain:b.dataset.drillPlayer,grading:'exploit'};go('setup')}if(b.dataset.villainAnswer)answerVillain(b.dataset.villainAnswer);if(b.dataset.villainRetry){const m=mistakes.find(m=>m.id===b.dataset.villainRetry);if(!m)return;selectedMode=10;session={index:0,total:1,used:new Set(),answers:[],current:withBaseline(structuredClone(m.spot)),feedback:null,reviewId:m.id};screen='session';renderVillain()}});
document.addEventListener('change',e=>{const t=e.target;if(t.dataset.villainFilter){filters[t.dataset.villainFilter]=t.value;villainSetup()}if(t.id==='spot-baseline-file'&&t.files[0])importSpotBaselines(t.files[0])});
